bool isPerfectSquareBS_26(long long n) { if (n < 0) return false; if (n <= 1) return true; long long lo = 1, hi = n; while (lo <= hi) { long long mid = lo + (hi - lo) / 2; if (mid * mid == n) return true; if (mid * mid < n) lo = mid + 1; else hi = mid - 1; } return false; }
int bsearchFirstOccur_27(const vector<int>& a, int t) { int lo = 0, hi = (int)a.size() - 1, ans = -1; while (lo <= hi) { int mid = lo + (hi - lo) / 2; if (a[mid] >= t) { if (a[mid] == t) ans = mid; hi = mid - 1; } else lo = mid + 1; } return ans; }
int bsearchLastOccur_27(const vector<int>& a, int t) { int lo = 0, hi = (int)a.size() - 1, ans = -1; while (lo <= hi) { int mid = lo + (hi - lo) / 2; if (a[mid] <= t) { if (a[mid] == t) ans = mid; lo = mid + 1; } else hi = mid - 1; } return ans; }
int findPeakElement_27(const vector<int>& a) { int lo = 0, hi = (int)a.size() - 1; while (lo < hi) { int mid = lo + (hi - lo) / 2; if (a[mid] < a[mid + 1]) lo = mid + 1; else hi = mid; } return lo; }
